import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next();
        StringBuilder output = new StringBuilder();
        int n = s.length();

        for (int i = 0; i < n; i++) {
            if (i + 3 <= n && s.substring(i, i + 3).equals("dot")) {
                output.append('.');
                i += 2;
            } else if (i + 2 <= n && s.substring(i, i + 2).equals("at")) {
                output.append('@');
                i += 1;
            } else {
                output.append(s.charAt(i));
            }
        }

        String result = output.toString();

        if (!result.isEmpty()) {
            if (result.charAt(0) == '.') {
                result = "dot" + result.substring(1);
            } else if (result.charAt(0) == '@') {
                result = "at" + result.substring(1);
            }
        }

        if (!result.isEmpty()) {
            if (result.charAt(result.length() - 1) == '.') {
                result = result.substring(0, result.length() - 1) + "dot";
            } else if (result.charAt(result.length() - 1) == '@') {
                result = result.substring(0, result.length() - 1) + "at";
            }
        }

        long atCount = result.chars().filter(c -> c == '@').count();

        if (atCount == 1) {
            System.out.println(result);
        } else {
            StringBuilder outputStr = new StringBuilder();
            boolean firstAt = true;
            for (char c : result.toCharArray()) {
                if (c == '@') {
                    if (firstAt) {
                        outputStr.append('@');
                        firstAt = false;
                    } else {
                        outputStr.append("at");
                    }
                } else {
                    outputStr.append(c);
                }
            }
            System.out.println(outputStr.toString());
        }
        sc.close();
    }
}
